CREATE TABLE stock_alerts (product_id INTEGER, stock INTEGER, raised_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TRIGGER low_stock AFTER UPDATE OF stock ON products
WHEN NEW.stock < 5 AND OLD.stock >= 5
BEGIN
    INSERT INTO stock_alerts (product_id, stock) VALUES (NEW.id, NEW.stock);
END;

